const box = document.getElementById('ai4a11y-agent-watch');
if (!box) return true;

function getLuminance(rgbStr) {
  const m = rgbStr.match(/\d+/g);
  if (!m) return null;
  const [r, g, b] = m.slice(0, 3).map(v => {
    const c = Number(v) / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(c1, c2) {
  const l1 = getLuminance(c1);
  const l2 = getLuminance(c2);
  if (l1 === null || l2 === null) return null;
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}

const rulesDetails = box.querySelector('.aw-rules');
if (rulesDetails) rulesDetails.open = true;

const controls = [
  box.querySelector('.aw-head'),
  box.querySelector('.aw-tell-input'),
  box.querySelector('.aw-tell button[type="submit"]'),
  box.querySelector('.aw-end'),
  box.querySelector('.aw-plan > summary'),
  box.querySelector('.aw-rules > summary'),
  box.querySelector('.aw-rules-toggle')
].filter(Boolean);

for (const ctrl of controls) {
  ctrl.focus();
  if (document.activeElement !== ctrl) return false;

  const style = window.getComputedStyle(ctrl);
  const outlineWidth = parseFloat(style.outlineWidth) || 0;
  const outlineColor = style.outlineColor;
  if (outlineWidth >= 2) {
    const ratio = contrast(outlineColor, 'rgb(255, 255, 255)');
    if (ratio !== null && ratio < 3.0) return false;
  }

  const rect = ctrl.getBoundingClientRect();
  if (rect.width < 24 || rect.height < 24) return false;

  const name = ctrl.getAttribute('aria-label') || ctrl.textContent || ctrl.placeholder || '';
  if (!name.trim()) return false;
}

if (rulesDetails) rulesDetails.open = false;
document.activeElement?.blur();
return true;

